/**
 * OpenAPI 3.1 spec for the Imagination Is All You Need HTTP API. Curated here (one source of truth), served at /api/openapi.json
 * with a self-contained docs page at /api/docs; any registered route missing from the curated list is appended as a
 * stub (see `withDiscovered`). `npm run openapi` writes the static copy to ../openapi.json.
 */
import { APP_VERSION } from './repoInfo.js';
type Op = Record<string, any>;
const ref = (n: string) => ({ $ref: `#/components/schemas/${n}` });
const json = (schema: any, description = 'OK') => ({ description, content: { 'application/json': { schema } } });
const err = { description: 'Error', content: { 'application/json': { schema: ref('Error') } } };
const IDEM_JSON = 'Same key + same request within 24 h returns the original response again (body idempotentReplay: true and response header Idempotent-Replayed: true, exposed via Access-Control-Expose-Headers): no second job, hold or charge. Aliases: header Client-Job-Id / X-Client-Job-Id, JSON body or query clientJobId / idempotencyKey. Same key + different job, body or endpoint → 409 exactly {"error":"idempotency_conflict","code":"idempotency_conflict","message":"This request was already sent with different details. Start a new one."}. Refused requests are not remembered.';
const p = (name: string, where: 'path' | 'query' | 'header' = 'path', schema: any = { type: 'string' }, description?: string, required = where === 'path') => ({ name, in: where, required, schema, ...(description ? { description } : {}) });
const idP = p('id', 'path', { type: 'string' }, 'Job id');
const storyIdP = p('id', 'path', { type: 'string' }, 'Story id (the story job id)');
const op = (tag: string, summary: string, extra: Op = {}): Op => ({ tags: [tag], summary, responses: { 200: json({ type: 'object' }) }, ...extra });

