export function buildSpec(serverUrl = 'http://localhost:8787') {
  return { openapi: '3.1.0', info: { title: 'Imagination Is All You Need API', version: APP_VERSION, description: 'Local API of Imagination Is All You Need (open rebuild on ComfyUI; not affiliated with Higgsfield). Mock backend by default. Prices are in credits (1 credit = $0.01).', license: { name: 'AGPL-3.0-or-later', identifier: 'AGPL-3.0-or-later' } },
    servers: [{ url: serverUrl }], tags: ['Jobs', 'Tools', 'Assets', 'Share', 'Usage', 'Discover', 'System'].map((name) => ({ name })),
    paths: CURATED, components: { schemas: SCHEMAS } };
}
/** Fastify path `/api/jobs/:id` → OpenAPI `/api/jobs/{id}`. */
export const toOpenApiPath = (u: string) => u.replace(/:([A-Za-z_]+)/g, '{$1}');
export function withDiscovered(spec: ReturnType<typeof buildSpec>, routes: { method: string; url: string }[]) {
  const paths: Record<string, Record<string, Op>> = JSON.parse(JSON.stringify(spec.paths));
  for (const r of routes) {
    if (!/^\/(api|s)\//.test(r.url) || r.url.startsWith('/api/openapi') || r.url === '/api/docs') continue;
    const k = toOpenApiPath(r.url); const m = r.method.toLowerCase(); if (m === 'head' || m === 'options') continue;
    if (!paths[k]?.[m]) (paths[k] ??= {})[m] = op('Other', `${r.method} ${r.url} (undocumented)`, { parameters: [...k.matchAll(/\{(\w+)\}/g)].map((x) => p(x[1])) });
  }
  return { ...spec, paths };
}

